package com.example

import com.example.ExamQuestionHelper.QSpec

internal object GeographyLiveExamClimateBank {
  private fun q(t: String, s: String, c: String, d1: String, d2: String, d3: String, e: String) =
    QSpec(t, s, c, listOf(d1, d2, d3), e)

  fun climateQuestions(): List<QSpec> {
    val t = "කාලගුණය, දේශගුණය හා ගෝලීය දේශගුණ කලාප"
    return listOf(
      q(t, "යම් ස්ථානයක කෙටි කාලයක් (පැය කිහිපයක් හෝ දින කිහිපයක්) තුළ වායුගෝලයේ පවතින ස්වභාවය හඳුන්වන්නේ කුමන නමකින්ද?",
        "කාලගුණය (Weather)", "දේශගුණය (Climate)", "සෘතු භේදය", "භූ විෂමතාව",
        "උෂ්ණත්වය, වර්ෂාපතනය, සුළඟ හා ආර්ද්‍රතාව වැනි සාධකවල කෙටිකාලීන තත්ත්වය කාලගුණයයි."),
      q(t, "යම් ප්‍රදේශයක අවම වශයෙන් වසර 30–35 ක් පමණ දිගු කාලයක් තුළ පැවති කාලගුණික තත්ත්වයන්ගේ සාමාන්‍යය කුමක්ද?",
        "දේශගුණය (Climate)", "කාලගුණ අනාවැකිය", "වායු පීඩන අනුක්‍රමණය", "තාප ප්‍රතිලෝමනය",
        "ලෝක කාලගුණ විද්‍යා සංවිධානය (WMO) අනුව වසර 30 ක සාමාන්‍යය දේශගුණය ලෙස ගණනය කෙරේ."),
      q(t, "වැසි, සුළං, අකුණු සහ වළාකුළු වැනි සියලු කාලගුණික සංසිද්ධි සිදුවන වායුගෝලයේ පහළම ස්තරය කුමක්ද?",
        "පරිවර්තී ගෝලය (Troposphere)", "අපවර්තී ගෝලය (Stratosphere)", "මධ්‍ය ගෝලය (Mesosphere)", "තාප ගෝලය (Thermosphere)",
        "පෘථිවි පෘෂ්ඨයේ සිට සාමාන්‍යයෙන් කි.මී. 8–18 ක් ඉහළට විහිදෙන Troposphere ස්තරයේ වායුගෝලීය ජල වාෂ්ප අඩංගු වේ."),
      q(t, "සූර්යයාගෙන් පැමිණෙන අහිතකර පාරජම්බුල (UV) කිරණ අවශෝෂණය කර ගන්නා ඕසෝන් ස්තරය පිහිටා ඇත්තේ කොහිද?",
        "අපවර්තී ගෝලයේ (Stratosphere)", "පරිවර්තී ගෝලයේ", "මධ්‍ය ගෝලයේ", "බහිර් ගෝලයේ",
        "අපවර්තී ගෝලයේ කි.මී. 15–35 අතර ඕසෝන් (O3) සාන්ද්‍රණය ඉහළ මට්ටමක පවතී."),
      q(t, "ජෙට් ගුවන් යානා දිගු දුර ගමන් සඳහා බහුලව භාවිත කරන, කැළඹීම් හා වළාකුළු අවම වායුගෝල ස්තරය කුමක්ද?",
        "අපවර්තී ගෝලයේ පහළ කොටස (Stratosphere)", "මධ්‍ය ගෝලය", "අයන ගෝලය", "පරිවර්තී ගෝලයේ පහළ කොටස",
        "අපවර්තී ගෝලයේ කුණාටු හා සිරස් වායු ධාරා අඩු නිසා ගුවන් ගමන් ස්ථාවර වේ."),
      q(t, "අභ්‍යවකාශයේ සිට පෘථිවි වායුගෝලයට ඇතුළු වන උල්කාපාත (Meteors) බහුලව දැවී අළු වී යන ස්තරය කවරේද?",
        "මධ්‍ය ගෝලය (Mesosphere)", "පරිවර්තී ගෝලය", "ඕසෝන් ස්තරය", "බහිර් ගෝලය",
        "මධ්‍ය ගෝලය වායුගෝලයේ සීතලම ස්තරය (-90°C පමණ) වන අතර උල්කාපාත දැවී යාම මෙහි සිදුවේ."),
      q(t, "රේඩියෝ තරංග පෘථිවියට පරාවර්තනය කර දුර සන්නිවේදනයට සහය වන ආරෝපිත අංශු සහිත ස්තරය කුමක්ද?",
        "අයන ගෝලය (Ionosphere - තාප ගෝලය තුළ)", "පරිවර්තී ගෝලය", "අපවර්තී ගෝලය", "ජල ගෝලය",
        "සූර්ය විකිරණ මගින් වායු අණු අයනීකරණය වීම නිසා Ionosphere ස්තරය ගොඩනැගේ."),
      q(t, "පෘථිවි වායුගෝලයේ වැඩිම ප්‍රතිශතයකින් (78% පමණ) අඩංගු වන ස්ථිර වායුව කුමක්ද?",
        "නයිට්‍රජන් (Nitrogen)", "ඔක්සිජන්", "කාබන් ඩයොක්සයිඩ්", "ආගන්",
        "වියළි වාතයේ නයිට්‍රජන් ~78.08%, ඔක්සිජන් ~20.95%, ආගන් ~0.93% හා CO2 ~0.04% අඩංගු වේ."),
      q(t, "පරිවර්තී ගෝලය තුළ උන්නතාංශය (Altitude) මීටර් 1,000 කින් ඉහළ යන විට සාමාන්‍යයෙන් උෂ්ණත්වය කොපමණ අඩු වේද?",
        "ආසන්න වශයෙන් 6.5°C (සාමාන්‍ය උෂ්ණත්ව බැස්මේ අනුපාතය)", "1°C කින්", "20°C කින්", "15°C කින්",
        "Normal Lapse Rate අනුව මීටර් 1,000 කට 6.5°C කින් (මීටර් 165 කට 1°C) උෂ්ණත්වය අඩු වේ."),
      q(t, "කාලගුණ මධ්‍යස්ථානයක උෂ්ණත්වමාන තැන්පත් කර තබන සුදු පැහැති, ලූවර් සහිත ලී පෙට්ටිය කුමක්ද?",
        "ස්ටීවන්සන් ආවරණය (Stevenson Screen)", "බැරෝමීටර පෙට්ටිය", "හයිග්‍රොමීටර ආවරණය", "රේඩාර් කුටිය",
        "සෘජු හිරු එළියෙන් හා වර්ෂාවෙන් තොරව පොළොවෙන් මීටර් 1.2 ක් ඉහළින් වායු උෂ්ණත්වය මැනීමට මෙය යොදා ගනී."),
      q(t, "ස්ටීවන්සන් ආවරණය සුදු පැහැයෙන් ආලේප කිරීමට ප්‍රධාන හේතුව කුමක්ද?",
        "සූර්ය තාපය පරාවර්තනය කර සත්‍ය සෙවණේ වායු උෂ්ණත්වය මැන ගැනීම", "කෘමීන් පලවා හැරීම", "රාත්‍රියේදී පහසුවෙන් දැකීම", "වර්ෂාවෙන් දිරාපත් නොවීම",
        "සුදු පැහැයට ඉහළ ඇල්බෙඩෝ අගයක් ඇති බැවින් අමතර තාප අවශෝෂණය වළකී."),
      q(t, "වායු පීඩනය (Atmospheric Pressure) මැනීම සඳහා භාවිත කරන උපකරණය කුමක්ද?",
        "බැරෝමීටරය (Barometer)", "ඇනිමෝමීටරය", "හයිග්‍රොමීටරය", "උපරිම-අවම උෂ්ණත්වමානය",
        "රසදිය හෝ නිර්ද්‍රව බැරෝමීටර මගින් මිලිබාර් (mb) හෝ හෙක්ටොපැස්කල් (hPa) වලින් පීඩනය මනී."),
      q(t, "සුළඟේ වේගය (Wind Speed) මැනීමට යොදා ගන්නා කැරකෙන කෝප්ප සහිත උපකරණය කුමක්ද?",
        "ඇනිමෝමීටරය (Anemometer)", "සුළං දිශා දර්ශකය (Wind Vane)", "හයිග්‍රොමීටරය", "සන්ෂයින් රෙකෝඩරය",
        "ඇනිමෝමීටරය මගින් සුළඟේ වේගය පැ.කි.මී. හෝ නොට්ස් වලින් දක්වයි."),
      q(t, "සුළඟ හමන දිශාව (Wind Direction) හඳුනා ගැනීමට භාවිත කරන උපකරණය කුමක්ද?",
        "සුළං දිශා දර්ශකය (Wind Vane)", "ඇනිමෝමීටරය", "වර්ෂා මානය", "ලයිසිමීටරය",
        "සුළං දිශා දර්ශකයේ ඊතලය සැමවිටම සුළඟ පැමිණෙන දිශාව වෙත හැරී පවතී."),
      q(t, "සාපේක්ෂ ආර්ද්‍රතාව (Relative Humidity) මැනීම සඳහා භාවිත කරන තෙත් හා වියළි බල්බ සහිත උපකරණය කුමක්ද?",
        "හයිග්‍රොමීටරය (Hygrometer)", "බැරෝමීටරය", "පයිරනෝමීටරය", "තර්මෝග්‍රැෆ්",
        "තෙත් හා වියළි බල්බ උෂ්ණත්වමාන දෙකේ පාඨාංක අන්තරයෙන් වාතයේ ජල වාෂ්ප සංතෘප්තිය ගණනය කෙරේ."),
      q(t, "දිනකට ලැබෙන දීප්තිමත් සූර්යාලෝක පැය ගණන මැනීම සඳහා යොදා ගන්නා වීදුරු ගෝල සහිත උපකරණය කුමක්ද?",
        "කැම්බල්-ස්ටෝක්ස් සූර්යාලෝක මානය (Sunshine Recorder)", "රේඩියෝසොන්ඩ්", "ලයිසිමීටරය", "සීස්මෝමීටරය",
        "වීදුරු ගෝලය මගින් නාභිගත වන කිරණ කාඩ්පත පිළිස්සීමෙන් හිරු එළිය පැය ගණන සටහන් වේ."),
      q(t, "වර්ෂා මානය (Rain Gauge) පොළොවේ ස්ථාපනය කිරීමේදී ගොඩනැගිලි හා ගස්වලින් ඈත්ව විවෘත ස්ථානයක තබන්නේ ඇයි?",
        "ගස් හෝ වහලවලින් ජලය වැටීම හා සුළං ආවරණ බලපෑම් වැළැක්වීමට", "සොරුන්ගෙන් ආරක්ෂා කිරීමට", "සතුන් බීම වැළැක්වීමට", "ඉක්මනින් වාෂ්ප වීමට",
        "බාධකයේ උස මෙන් දෙගුණයකවත් දුරින් තැබීම නිවැරදි මිනුම් ලබා ගැනීමේ රීතියයි."),
      q(t, "සමක ප්‍රදේශවල සහ ශ්‍රී ලංකාවේ අන්තර් මෝසම් කාලවලදී දහවල් අධික උණුසුම නිසා ඇතිවන වර්ෂාපතන වර්ගය කුමක්ද?",
        "සංවහන වර්ෂාව (Convectional Rainfall)", "භූ විෂමතා වර්ෂාව", "වාසුළි වර්ෂාව", "හිම කැට වර්ෂාව",
        "රත් වූ තෙත් වාතය සිරස්ව ඉහළ නැග සිසිල් වී සවස් කාලයේ ගිගුරුම් සහිත වැසි ලබා දෙයි."),
      q(t, "තෙත් වායු ධාරාවක් කඳු වැටියක ගැටී ඉහළ නැගීමෙන් සුළං මුහුණත බෑවුමට ලැබෙන වර්ෂාව කුමක්ද?",
        "භූ විෂමතා / කඳු ආශ්‍රිත වර්ෂාව (Orographic Rainfall)", "සංවහන වර්ෂාව", "පෙරමුණු වර්ෂාව", "කෘත්‍රිම වර්ෂාව",
        "ශ්‍රී ලංකාවේ නිරිතදිග මෝසම මගින් මධ්‍යම කඳුකරයේ බටහිර බෑවුම්වලට අධික භූ විෂමතා වර්ෂාව ලැබේ."),
      q(t, "කඳු වැටියක සුළඟට ප්‍රතිවිරුද්ධ පැත්තේ පිහිටි, උණුසුම් වියළි වාතය පහළ බැසීම නිසා වියළි කාලගුණයක් පවතින ප්‍රදේශය කුමක්ද?",
        "වැසි මුවාව (Rain Shadow Area)", "සමෝච්ච කලාපය", "පෙරමුණු කලාපය", "මෝය කලාපය",
        "මෝසම් සුළං කඳු වැටි පසු කර පහළ බසින විට සම්පීඩනයෙන් රත් වී වියළි බව ඇති කරයි."),
      q(t, "උණුසුම් වායු ස්කන්ධයක් සහ සීතල වායු ස්කන්ධයක් එකිනෙක හමුවන සීමාවේදී ඇතිවන වර්ෂා වර්ගය කුමක්ද?",
        "පෙරමුණු / වාතාග්‍ර වර්ෂාව (Frontal / Cyclonic Rainfall)", "භූ විෂමතා වර්ෂාව", "සංවහන වර්ෂාව", "උදම් වර්ෂාව",
        "සමශීතෝෂ්ණ කලාපවල උණුසුම් හා සීතල වායු ස්කන්ධ ගැටීමේදී සැහැල්ලු උණුසුම් වාතය ඉහළ නැග වැසි ඇති කරයි."),
      q(t, "ඉහළ අහසේ ගෝවා මලක හෝ හිම කන්දක ආකාරයෙන් සිරස්ව ඉහළට වැඩෙන, ගිගුරුම් සහිත අකුණු වැසි ගෙනෙන වළාකුළු වර්ගය කුමක්ද?",
        "කැටි වැහි වළාකුළු (Cumulonimbus)", "කෙඳි වළාකුළු (Cirrus)", "ස්තර වළාකුළු (Stratus)", "උස් කෙඳි වළාකුළු (Cirrocumulus)",
        "Cumulonimbus වළාකුළු කි.මී. 12–15 ක් දක්වා ඉහළ නැග දැඩි වර්ෂාව, අකුණු සහ හිම කැට ඇති කරයි."),
      q(t, "ඉතා ඉහළ උන්නතාංශයේ (මීටර් 6,000 ට ඉහළින්) පිහාටු හෝ කෙඳි ආකාරයෙන් පෙනෙන අයිස් ස්ඵටිකමය වළාකුළු මොනවාද?",
        "සිරස් / කෙඳි වළාකුළු (Cirrus)", "නිම්බොස්ට්‍රේටස්", "කියුමියුලස්", "ඇල්ටොස්ට්‍රේටස්",
        "Cirrus වළාකුළු වර්ෂාව නොදෙන නමුත් ඉදිරියේදී කාලගුණ වෙනසක් සිදුවිය හැකි බව හඟවයි."),
      q(t, "මුළු අහසම අළු පැහැති ඝන තට්ටුවකින් වසාගෙන නොනවතින සැහැල්ලු හෝ මධ්‍යස්ථ වැසි ලබා දෙන පහළ වළාකුළු වර්ගය කුමක්ද?",
        "නිම්බොස්ට්‍රේටස් (Nimbostratus)", "සිරස් (Cirrus)", "කියුමියුලස් (Cumulus)", "සිරෝස්ට්‍රේටස්",
        "මෝසම් කාලයේදී දිගු වේලාවක් පවතින වැසි සඳහා Nimbostratus වළාකුළු ප්‍රධාන වේ."),
      q(t, "සමකයේ සිට 5°N හා 5°S අතර පිහිටි, සුළං ඉතා මන්දගාමී හා වාතය ඉහළ නගින අඩු පීඩන කලාපය හඳුන්වන්නේ කෙසේද?",
        "ඩෝල්ඩ්‍රම්ස් / අන්තර් නිවර්තන අභිසාරී කලාපය (ITCZ / Doldrums)", "අශ්ව අක්ෂාංශ (Horse Latitudes)", "ඝෝෂාකාරී හතළිහ", "ධ්‍රැවීය අධි පීඩනය",
        "උතුරු හා දකුණු වෙළඳ සුළං හමුවන ITCZ කලාපය සංවහන වැසි සඳහා ප්‍රසිද්ධය."),
      q(t, "30°N සහ 30°S අක්ෂාංශ ආසන්නයේ වාතය පහළට බැසීම නිසා වියළි කාන්තාර බිහිවීමට දායක වන පීඩන කලාපය කුමක්ද?",
        "උප නිවර්තන අධි පීඩන කලාපය (Subtropical High / Horse Latitudes)", "සමක අඩු පීඩන කලාපය", "උප ධ්‍රැවීය අඩු පීඩන කලාපය", "මෝසම් අගාධය",
        "සහාරා, කලහාරි සහ ඕස්ට්‍රේලියානු කාන්තාර බහුලව 20°–30° අක්ෂාංශ අතර අධි පීඩන කලාපයේ පිහිටයි."),
      q(t, "උප නිවර්තන අධි පීඩන කලාපයේ සිට සමක අඩු පීඩන කලාපය දෙසට හමන නියත ග්‍රහලෝක සුළං මොනවාද?",
        "වෙළඳ සුළං (Trade Winds)", "බටහිර සුළං (Westerlies)", "ධ්‍රැවීය නැගෙනහිර සුළං", "මුහුදු සුළං",
        "කොරියෝලිස් බලය නිසා උතුරු අර්ධගෝලයේදී ඊසාන වෙළඳ සුළං ලෙසත් දකුණේදී ගිනිකොන වෙළඳ සුළං ලෙසත් හමයි."),
      q(t, "පෘථිවියේ භ්‍රමණය නිසා හමන සුළං හා සාගර දියවැල් උතුරු අර්ධගෝලයේදී දකුණටත් දකුණු අර්ධගෝලයේදී වමටත් හැරවීමේ ආචරණය කුමක්ද?",
        "කොරියෝලිස් ආචරණය (Coriolis Effect)", "හරිතාගාර ආචරණය", "ඇල්බෙඩෝ ආචරණය", "තාප ප්‍රතිලෝමනය",
        "ප්‍රංශ විද්‍යාඥ Gaspard-Gustave de Coriolis විසින් පැහැදිලි කළ මෙම බලය සමකයේදී ශුන්‍ය වේ."),
      q(t, "දක්ෂිණ අර්ධගෝලයේ 40°S අක්ෂාංශ ආසන්නයේ ගොඩබිම් බාධක නොමැති නිසා ඉතා වේගයෙන් හමන බටහිර සුළං හඳුන්වන නම කුමක්ද?",
        "ගිගුරුම් සහිත හතළිහ (Roaring Forties)", "වෙළඳ සුළං", "ඩෝල්ඩ්‍රම්ස්", "හර්මැටන් සුළං",
        "40°S හි Roaring Forties, 50°S හි Furious Fifties සහ 60°S හි Shrieking Sixties ලෙස හැඳින්වේ."),
      q(t, "දිවා කාලයේදී ගොඩබිම සාගරයට වඩා ඉක්මනින් රත් වී ගොඩබිම මත අඩු පීඩනයක් ඇති වීම නිසා හමන සුළඟ කුමක්ද?",
        "මුහුදු සුළඟ (Sea Breeze)", "ගොඩබිම් සුළඟ (Land Breeze)", "කඳු සුළඟ", "ධ්‍රැවීය සුළඟ",
        "දහවල් කාලයේදී සිසිල් සාගරයේ සිට උණුසුම් ගොඩබිම දෙසට මුහුදු සුළං හමා එයි."),
      q(t, "රාත්‍රී කාලයේදී ගොඩබිම ඉක්මනින් සිසිල් වීම නිසා ගොඩබිමේ සිට උණුසුම් සාගරය දෙසට හමන සුළඟ කුමක්ද?",
        "ගොඩබිම් සුළඟ (Land Breeze)", "මුහුදු සුළඟ", "චිනූක් සුළඟ", "මෝසම් සුළඟ",
        "රාත්‍රියේදී සාගරය සෙමින් සිසිල් වන බැවින් සාගරය මත සාපේක්ෂ අඩු පීඩනයක් පවතී."),
      q(t, "'මෝසම්' (Monsoon) යන වචනය බිඳී ආ අරාබි 'මව්සිම්' (Mausim) යන්නෙහි අර්ථය කුමක්ද?",
        "සෘතුව (Season)", "කුණාටුව", "වැස්ස", "කාන්තාරය",
        "සෘතු අනුව සම්පූර්ණයෙන්ම දිශාව මාරු කර හමන සුළං පද්ධති මෝසම් සුළං නම් වේ."),
      q(t, "ශ්‍රී ලංකාවට මැයි සිට සැප්තැම්බර් දක්වා කාලය තුළ නිරිතදිග මෝසම හමා එන්නේ ඇයි?",
        "ග්‍රීෂ්ම සෘතුවේදී මධ්‍යම ආසියානු හා ඉන්දියානු ගොඩබිමේ ඇතිවන ප්‍රබල අඩු පීඩන කලාපය ආකර්ෂණය වීමෙන්", "ධ්‍රැවීය හිම දියවීමෙන්", "සූර්යග්‍රහණ නිසා", "ශාන්තිකර සුළි සුළං නිසා",
        "දකුණු ඉන්දියන් සාගරයේ ගිනිකොන වෙළඳ සුළං සමකය පසු කර කොරියෝලිස් බලයෙන් දකුණට හැරී නිරිතදිග මෝසම බවට පත්වේ."),
      q(t, "ශ්‍රී ලංකාවට දෙසැම්බර් සිට පෙබරවාරි දක්වා ඊසානදිග මෝසම් වර්ෂාව ගෙන එන සුළං හමා එන්නේ කුමන ප්‍රදේශයේ සිටද?",
        "ආසියානු මහාද්වීපයේ සීතල අධි පීඩන කලාපයේ සිට බෙංගාල බොක්ක හරහා", "අරාබි මුහුද හරහා", "මැඩගස්කර් දෙසින්", "පැසිෆික් සාගරයෙන්",
        "බෙංගාල බොක්ක හරහා පැමිණීමේදී තෙතමනය උරාගෙන ශ්‍රී ලංකාවේ උතුරු හා නැගෙනහිරට වැසි ලබා දෙයි."),
      q(t, "ශ්‍රී ලංකාවේ නිරිතදිග මෝසම් කාලයේදී මධ්‍යම කඳුකරයේ වැසි මුවාවේ පිහිටි නැගෙනහිර බෑවුම්වලට හමන උණුසුම් වියළි සුළඟ කුමක්ද?",
        "කච්චාන් සුළඟ (Kachchan Wind)", "මිස්ට්‍රල් සුළඟ", "හර්මැටන් සුළඟ", "බෝරා සුළඟ",
        "බදුල්ල, අම්පාර සහ මඩකලපුව ප්‍රදේශවලට ජූනි–අගෝස්තු අතර හමන වියළි සුළඟ කච්චාන් නම් වේ."),
      q(t, "උතුරු ඇමරිකාවේ රොකී කඳු වැටියේ නැගෙනහිර බෑවුම් දිගේ පහළ බසිමින් ශීත හිම ඉක්මනින් දිය කරන උණුසුම් සුළඟ කුමක්ද?",
        "චිනූක් (Chinook - 'Snow Eater')", "මිස්ට්‍රල්", "සිරොක්කෝ", "පැම්පෙරෝ",
        "ඇල්ප්ස් කඳුකරයේ ෆෝන් (Föhn) සුළඟට සමාන මෙම සුළඟ රොකී කඳු පාමුල උෂ්ණත්වය පැය කිහිපයකින් ඉහළ නංවයි."),
      q(t, "බටහිර අප්‍රිකාවේ සහාරා කාන්තාරයේ සිට ගිනියා වෙරළ දෙසට හමන අතිශය වියළි හා දූවිලි සහිත සුළඟ ('වෛද්‍යවරයා') කුමක්ද?",
        "හර්මැටන් (Harmattan)", "බ්ලිසාර්ඩ්", "ටෝනේඩෝ", "ලෙවැන්ටර්",
        "තෙත් වෙරළබඩ උණුසුම් ආර්ද්‍රතාව අඩු කරන බැවින් එය 'The Doctor' ලෙසද හැඳින්වේ."),
      q(t, "උතුරු අප්‍රිකාවේ සිට මධ්‍යධරණී මුහුද හරහා දකුණු යුරෝපය දෙසට හමන උණුසුම් දූවිලි සහිත සුළඟ කුමක්ද?",
        "සිරොක්කෝ (Sirocco)", "මිස්ට්‍රල්", "බෝරා", "චිනූක්",
        "සිරොක්කෝ සුළඟ මධ්‍යධරණී මුහුද හරහා තෙතමනය උරාගෙන ඉතාලියට 'රුධිර වැසි' (රතු දූවිලි වැසි) ගෙන එයි."),
      q(t, "ශ්‍රී ලංකාවේ නිරිතදිග ප්‍රදේශයට වැඩිම වාර්ෂික වර්ෂාපතනයක් (මි.මී. 5,000 ට අධික) වාර්තා වී ඇති ස්ථානයක් වන්නේ කුමක්ද?",
        "වටවල / මාලිබොඩ ප්‍රදේශ", "හම්බන්තොට", "මන්නාරම", "මඩකලපුව",
        "නුවරඑළිය දිස්ත්‍රික්කයේ වටවල හා කෑගල්ල දිස්ත්‍රික්කයේ මාලිබොඩ ප්‍රදේශ අධික වැසි ලබයි."),
      q(t, "ශ්‍රී ලංකාවේ අඩුම වාර්ෂික වර්ෂාපතනයක් (මි.මී. 1,000 ට අඩු) ලැබෙන අර්ධ ශුෂ්ක කලාප දෙක මොනවාද?",
        "මන්නාරම - යාපනය අර්ධද්වීපය සහ හම්බන්තොට - යාල ප්‍රදේශය", "රත්නපුර සහ කළුතර", "මහනුවර සහ මාතලේ", "ගාල්ල සහ මාතර",
        "මෝසම් සුළං දෙකම මෙම කලාප හරහා වියළිව හෝ සමාන්තරව ගමන් කිරීම ඊට හේතුවයි."),
      q(t, "මධ්‍යධරණී දේශගුණ කලාපයේ (Mediterranean Climate - Cs) ඇති සුවිශේෂීම කාලගුණික ලක්ෂණය කුමක්ද?",
        "උණුසුම් වියළි ග්‍රීෂ්ම සෘතුවක් සහ සෞම්‍ය තෙත් ශීත සෘතුවක් පැවතීම", "වසර පුරා නොනවතින සංවහන වැසි", "වසර පුරා හිම පතනය", "ග්‍රීෂ්මයේ පමණක් වැසි ලැබීම",
        "ශීත සෘතුවේදී බටහිර සුළං මගින් මධ්‍යධරණී ප්‍රදේශයට වැසි ලැබෙන අතර ග්‍රීෂ්මයේදී වෙළඳ සුළං යටතේ වියළි වේ."),
      q(t, "සමක වැසි වනාන්තර දේශගුණයේ (Af - Tropical Rainforest) ප්‍රධාන ලක්ෂණය කුමක්ද?",
        "වසර පුරා අධික උෂ්ණත්වය (~27°C) සහ නිරන්තර සංවහන වර්ෂාපතනය", "දිගු වියළි සෘතුවක් පැවතීම", "සෘතු හතරක් පැහැදිලිව වෙන්වීම", "වාර්ෂික උෂ්ණත්ව පරාසය 30°C ඉක්මවීම",
        "ඇමසන්, කොංගෝ සහ මැලේසියානු දූපත් සමූහය මෙම කලාපයට අයත් වේ."),
      q(t, "නිවර්තන සැවානා දේශගුණය (Aw - Tropical Savanna) සමක දේශගුණයෙන් වෙනස් වන්නේ කෙසේද?",
        "පැහැදිලි තෙත් සෘතුවක් සහ පැහැදිලි වියළි සෘතුවක් පැවතීමෙන්", "අධික හිම පතනයෙන්", "සුළං නොමැති වීමෙන්", "උෂ්ණත්වය 0°C ට අඩු වීමෙන්",
        "උස තෘණ සහ විසිරුණු කුඩා ගස් (Acacia, Baobab) සහිත තණබිම් සැවානා කලාපයේ ලක්ෂණයයි."),
      q(t, "වොල්ඩිමීර් කෝපන්ගේ (Köppen) දේශගුණ වර්ගීකරණයේදී 'B' අකුරෙන් නිරූපණය වන දේශගුණ කාණ්ඩය කුමක්ද?",
        "ශුෂ්ක හා අර්ධ ශුෂ්ක දේශගුණය (Arid / Dry Climates)", "නිවර්තන තෙත් දේශගුණය", "ධ්‍රැවීය හිම දේශගුණය", "සෞම්‍ය කලාපීය දේශගුණය",
        "වාෂ්පීකරණ විභවය වර්ෂාපතනයට වඩා වැඩි කාන්තාර (BW) හා ස්ටෙප් (BS) ප්‍රදේශ 'B' කාණ්ඩයට වැටේ."),
      q(t, "විශාල මහාද්වීප අභ්‍යන්තරයේ පිහිටි ගොබි (Gobi) සහ ටක්ලමකන් කාන්තාර ඇතිවීමට බලපෑ ප්‍රධාන හේතුව කුමක්ද?",
        "සාගරවලින් අධික දුරකින් පිහිටීම (Continentality) හා උස කඳු වැටි මගින් තෙතමනය අවහිර කිරීම", "සීතල සාගර දියවැල්", "අධික ගිනිකඳු ක්‍රියාකාරිත්වය", "භූගත ලවණතාව",
        "හිමාලය හා අනෙකුත් කඳු වැටි මෝසම් තෙතමනය මධ්‍ය ආසියාවට යාම වළක්වයි."),
      q(t, "නැමීබ් (Namib) සහ ඇටකාමා (Atacama) කාන්තාර මුහුදු වෙරළ ආසන්නයේ පිහිටා තිබුණද අතිශයින් වියළි වන්නේ ඇයි?",
        "වෙරළට සමාන්තරව ගලා යන සීතල සාගර දියවැල් (බෙන්ගුලා හා හම්බෝල්ට්) වායු ඉහළ නැගීම වළක්වන බැවින්", "උණුසුම් දියවැල් නිසා", "ගස් කැපීම නිසා", "භූ කම්පන නිසා",
        "සීතල ජලය මත වාතය සිසිල් වී ස්ථාවර වන බැවින් වැසි වළාකුළු නොසෑදී මීදුම පමණක් ඇති වේ."),
      q(t, "තණබිම් සහිත උතුරු ධ්‍රැව ආසන්නයේ පිහිටි, පස යට නිත්‍ය තුහින (Permafrost) ස්තරයක් ඇති දේශගුණ කලාපය කුමක්ද?",
        "ටුන්ඩ්‍රා දේශගුණ කලාපය (Tundra - ET)", "ටයිගා වනාන්තර කලාපය", "මධ්‍යධරණී කලාපය", "සැවානා කලාපය",
        "ටුන්ඩ්‍රා කලාපයේ උණුසුම්ම මාසයේ සාමාන්‍ය උෂ්ණත්වය 0°C – 10°C අතර පවතින අතර පාසි හා ලයිකන වැවේ."),
      q(t, "උතුරු අර්ධගෝලයේ උප ආක්ටික් කලාපයේ පිහිටි, කේතුධර වනාන්තර (Coniferous Forests) බහුල ජෛව පද්ධතිය කුමක්ද?",
        "ටයිගා / බෝරියල් වනාන්තර කලාපය (Taiga)", "සැවානා තණබිම්", "සමක වැසි වනාන්තර", "චැපරල් ලඳු කැලෑ",
        "පයින්, ස්පෘස් සහ ෆර් වැනි ඉදිකටු පත්‍ර සහිත ගස් රුසියාව හා කැනඩාව පුරා ටයිගා වනාන්තර සාදයි."),
      q(t, "ස්වභාවික හරිතාගාර ආචරණය (Natural Greenhouse Effect) පෘථිවියේ ජීවය පැවතීමට අත්‍යවශ්‍ය වන්නේ ඇයි?",
        "පෘථිවි පෘෂ්ඨයෙන් පිටවන දිගු තරංග අධෝරක්ත තාපය රඳවාගෙන සාමාන්‍ය උෂ්ණත්වය +15°C මට්ටමේ පවත්වා ගන්නා බැවින්", "UV කිරණ නිපදවන බැවින්", "සුළං නවත්වන බැවින්", "ඔක්සිජන් වැඩි කරන බැවින්",
        "හරිතාගාර ආචරණය නොතිබුණේ නම් පෘථිවියේ සාමාන්‍ය උෂ්ණත්වය -18°C පමණ වනු ඇත."),
      q(t, "මිනිස් ක්‍රියාකාරකම් නිසා වර්ධනය වන ගෝලීය උණුසුම් වීමට ප්‍රධාන වශයෙන්ම දායක වන හරිතාගාර වායු මොනවාද?",
        "කාබන් ඩයොක්සයිඩ් (CO2), මීතේන් (CH4) සහ නයිට්‍රස් ඔක්සයිඩ් (N2O)", "නයිට්‍රජන් සහ ඔක්සිජන්", "හීලියම් සහ නියෝන්", "හයිඩ්‍රජන් පමණි",
        "ෆොසිල ඉන්ධන දහනය, වන විනාශය හා කෘෂිකර්මාන්තය මගින් CO2 සහ CH4 ප්‍රමාණය ඉහළ යයි."),
      q(t, "පෘථිවි පෘෂ්ඨයේ සූර්ය විකිරණ පරාවර්තනය කිරීමේ හැකියාව හඳුන්වන 'ඇල්බෙඩෝ' (Albedo) අගය ඉහළම පෘෂ්ඨය කුමක්ද?",
        "නැවුම් සුදු හිම සහ අයිස් පෘෂ්ඨය (80%–90%)", "තද පැහැති සාගර ජලය", "සදාහරිත වැසි වනාන්තර", "තාර දැමූ මහාමාර්ග",
        "හිම දියවී යාමේදී ඇල්බෙඩෝ අගය අඩු වී සාගරය හෝ පොළොව වැඩි තාපයක් උරා ගැනීම Ice-Albedo Feedback නම් වේ."),
      q(t, "'එල් නිනෝ' (El Niño) සංසිද්ධිය සිදුවන විට නිරක්ෂීය පැසිෆික් සාගරයේ කුමන වෙනසක් සිදුවේද?",
        "මධ්‍යම හා නැගෙනහිර පැසිෆික් සාගරයේ මතුපිට ජල උෂ්ණත්වය අසාමාන්‍ය ලෙස ඉහළ යාම", "ඇට්ලාන්ටික් සාගරය සම්පූර්ණයෙන් මිදීම", "පේරු වෙරළේ සීතල ජලය ඉහළට ගැලීම වැඩි වීම", "සමකයේ අයිස් කඳු සෑදීම",
        "වෙළඳ සුළං දුර්වල වීම නිසා උණුසුම් ජලය දකුණු ඇමරිකා වෙරළ දෙසට ගලා ගොස් ගෝලීය කාලගුණය වෙනස් කරයි."),
      q(t, "එල් නිනෝ තත්ත්වය හේතුවෙන් දකුණු ආසියාවට, ඕස්ට්‍රේලියාවට සහ ඉන්දුනීසියාවට බහුලව ඇතිවිය හැකි බලපෑම කුමක්ද?",
        "මෝසම් වර්ෂාපතනය දුර්වල වී නියඟ හා ලැව්ගිනි අවදානම ඉහළ යාම", "අධික හිම කුණාටු ඇති වීම", "ටුන්ඩ්‍රා දේශගුණය ඇති වීම", "සුනාමි රළ ඇති වීම",
        "එල් නිනෝ කාලවලදී බටහිර පැසිෆික් සහ ඉන්දියන් සාගර කලාපවල වර්ෂාව අඩු වන අතර පේරු වෙරළට ගංවතුර ඇති වේ."),
      q(t, "නිවර්තන සුළි සුළං (Tropical Cyclones / Hurricanes / Typhoons) උත්පාදනය වීම සඳහා අවශ්‍ය අවම සාගර ජල උෂ්ණත්වය කොපමණද?",
        "26.5°C හෝ ඊට වැඩි උෂ්ණත්වයක්", "5°C ට අඩු", "10°C පමණ", "50°C ට වැඩි",
        "උණුසුම් සාගර ජලයෙන් ලැබෙන ගුප්ත තාපය සුළි සුළඟක ප්‍රධාන ශක්ති ප්‍රභවයයි."),
      q(t, "නිවර්තන සුළි සුළඟක් (Cyclone) සමකයේ සිට 5° කලාපය තුළ (0°–5°) කිසිදා හට නොගන්නේ ඇයි?",
        "සමකය ආසන්නයේ කොරියෝලිස් බලය ඉතා දුර්වල හෝ ශුන්‍ය වන බැවින් භ්‍රමණයක් ඇති නොවන නිසා", "සමකයේ ජලය සීතල නිසා", "සමකයේ වාතය නැති නිසා", "කඳු වැටි වැඩි නිසා",
        "වාතය අඩු පීඩන මධ්‍යය වටා කැරකැවීමට ප්‍රමාණවත් කොරියෝලිස් බලයක් අවශ්‍ය වේ."),
      q(t, "සුළි සුළඟක මධ්‍යයේ පිහිටි, සුළං සන්සුන් හා අහස පැහැදිලිව පවතින කලාපය හඳුන්වන්නේ කුමන නමකින්ද?",
        "සුළි සුළඟේ ඇස (Eye of the Cyclone)", "ඇසේ පවුර (Eye Wall)", "සර්පිලාකාර වළා පටිය", "පෙරමුණු අගාධය",
        "Eye Wall කලාපයේ දරුණුම සුළං හා වැසි පවතින නමුත් ඇස තුළ වාතය සෙමින් පහළ බසී."),
      q(t, "උතුරු අර්ධගෝලයේ අඩු පීඩන මධ්‍යස්ථානයක් (Cyclone) වටා සුළං භ්‍රමණය වන දිශාව කුමක්ද?",
        "ඔරලෝසු කටුවට ප්‍රතිවිරුද්ධ දිශාවට (Counter-clockwise / Anticlockwise)", "ඔරලෝසු කටුවේ දිශාවට", "සෘජුව උතුරට පමණි", "ඉහළ සිට පහළට පමණි",
        "දකුණු අර්ධගෝලයේදී සුළි සුළං ඔරලෝසු කටුවේ දිශාවට (Clockwise) භ්‍රමණය වේ."),
      q(t, "නාගරික ප්‍රදේශ අවට ග්‍රාමීය ප්‍රදේශවලට වඩා උණුසුම් වීමේ සංසිද්ධිය ('නාගරික තාප දූපත' - Urban Heat Island) ඇති වන්නේ ඇයි?",
        "කොන්ක්‍රීට්, ඇස්ෆල්ට් පෘෂ්ඨ තාපය රඳවා ගැනීම, වෘක්ෂලතා අඩුවීම සහ වාහන/කර්මාන්තශාලා තාප විමෝචනය නිසා", "වැසි වැඩි නිසා", "මුහුදු මට්ටම ඉහළ යාම නිසා", "ධ්‍රැවීය සුළං නිසා",
        "හරිත අවකාශ හා ජලාශ වැඩි කිරීමෙන් නාගරික තාප දූපත් බලපෑම අවම කළ හැක."),
      q(t, "ඕසෝන් ස්තරය ක්ෂය වීමට ප්‍රධාන වශයෙන්ම හේතු වූ මිනිසා විසින් නිපදවූ රසායනික සංයෝග මොනවාද?",
        "ක්ලෝරෝෆ්ලෝරෝකාබන් (CFCs) සහ හේලෝන් වායු", "ඔක්සිජන් සහ හීලියම්", "නයිට්‍රජන් සහ ආගන්", "කැල්සියම් කාබනේට්",
        "ශීතකරණ හා එයරසෝල්වල භාවිත කළ CFC සීමා කිරීමට 1987 මොන්ට්‍රියල් සම්මුතිය (Montreal Protocol) අත්සන් කෙරිණි."),
      q(t, "ශීත රාත්‍රියක පොළොවට ආසන්න වායු ස්තරය ඉහළ වායු ස්තරයට වඩා සිසිල් වී දූෂිත වායු හා මීදුම පොළොව අසල රැඳීමේ තත්ත්වය කුමක්ද?",
        "උෂ්ණත්ව ප්‍රතිලෝමනය (Temperature Inversion)", "සංවහන ධාරා", "වැසි මුවාව", "අන්තර් නිවර්තන අභිසාරිතාව",
        "සාමාන්‍යයෙන් උස වැඩිවත්ම සිසිල් වුවද ප්‍රතිලෝමනයේදී උණුසුම් වාතය පියනක් මෙන් සිසිල් වාතය සිර කරයි."),
      q(t, "පොළොවට ආසන්න වාතයේ ජල වාෂ්ප ඝනීභවනය වීමෙන් පෘෂ්ඨය මත ඇතිවන ජල බිඳිති හඳුන්වන්නේ කුමන නමකින්ද?",
        "පින්න (Dew)", "හිම (Snow)", "හිම කැට (Hail)", "වැහි කෝඩය",
        "රාත්‍රියේදී තණකොළ හා පත්‍ර පිණි ලක්ෂ්‍යයට (Dew Point) වඩා සිසිල් වූ විට පින්න සෑදේ."),
      q(t, "උෂ්ණත්වය 0°C (හිමාංකය) ට වඩා පහළ බැස ඇති විට ජල වාෂ්ප ද්‍රව නොවී කෙළින්ම සුදු අයිස් ස්ඵටික ලෙස පොළොවේ තැන්පත් වීම කුමක්ද?",
        "තුහින / මල් තුහින (Frost / Hoar Frost)", "මීදුම (Fog)", "පින්න", "හිම මිදුණු වැසි",
        "ශ්‍රී ලංකාවේ නුවරඑළිය ප්‍රදේශයේ දෙසැම්බර්-ජනවාරි සීතල රාත්‍රීන්හි මල් තුහින පතිත වේ."),
      q(t, "සූර්ය විකිරණයට ඉහළින් පවතින කඳු මුදුනකට වඩා සමුද්‍ර මට්ටම ආසන්න නිම්නයක් උණුසුම් වීමට ප්‍රධාන හේතුව කුමක්ද?",
        "පහළ උන්නතාංශයේදී වායු ඝනත්වය හා ජල වාෂ්ප වැඩි නිසා පෘථිවි භෞමික විකිරණය වැඩිපුර අවශෝෂණය කිරීම", "සමුද්‍ර මට්ටමේ සූර්යයා ළඟ වීම", "කඳු මුදුනේ වාතය ඝන වීම", "ගුරුත්වාකර්ෂණය නැති වීම",
        "වායුගෝලය ප්‍රධාන වශයෙන් රත් වන්නේ පෘථිවි පෘෂ්ඨයෙන් පිටවන අධෝරක්ත විකිරණය මගින් පහළ සිට ඉහළටය."),
      q(t, "ගොඩබිම හා ජලය රත්වීමේ වේගය අනුව ගත් කල ග්‍රීෂ්මයේදී ගොඩබිම හා ජලය හැසිරෙන්නේ කෙසේද?",
        "ගොඩබිම ජලයට වඩා ඉක්මනින් රත් වී ඉක්මනින් සිසිල් වේ", "ජලය ඉක්මනින් රත් වේ", "දෙකම සමාන වේගයෙන් රත් වේ", "ගොඩබිම කිසිදා රත් නොවේ",
        "ජලයේ ඉහළ විශිෂ්ට තාප ධාරිතාව හා තාප විනිවිද යාම නිසා සාගර රත්වීමට හා සිසිල් වීමට වැඩි කලක් ගත වේ."),
      q(t, "සාගර ආශ්‍රිත දූපත් හා වෙරළබඩ නගරවල (උදා: කොළඹ) දෛනික හා වාර්ෂික උෂ්ණත්ව අන්තරය කුඩා වන්නේ ඇයි?",
        "සාගරයේ සමතුලිත කිරීමේ බලපෑම (Maritime Influence) නිසා", "කඳු වැටි වැඩි නිසා", "වනාන්තර නැති නිසා", "වායු පීඩනය ශුන්‍ය නිසා",
        "මහාද්වීප අභ්‍යන්තර නගරවල (Continental Climate) ග්‍රීෂ්ම-ශීත උෂ්ණත්ව වෙනස ඉතා අධික වේ."),
      q(t, "අත්ලාන්තික් සාගරයේ උණුසුම් 'ගල්ෆ් දියවැල' (Gulf Stream / North Atlantic Drift) බටහිර යුරෝපයට ඇති කරන ධනාත්මක බලපෑම කුමක්ද?",
        "සමාන අක්ෂාංශයේ පිහිටි කැනඩාවට වඩා බටහිර යුරෝපීය වරායන් ශීත සෘතුවේදී අයිස්වලින් තොරව පවත්වා ගැනීම", "කාන්තාර ඇති කිරීම", "සමක දේශගුණය ගෙන ඒම", "වර්ෂාව සම්පූර්ණයෙන් නැවැත්වීම",
        "නෝර්වේ හි උතුරු වරායන් පවා ශීත සෘතුවේදී නාවික ගමනාගමනයට විවෘතව පවතින්නේ මෙම උණුසුම් දියවැල නිසාය."),
      q(t, "සීතල 'ලැබ්‍රඩෝ දියවැල' (Labrador Current) සහ උණුසුම් 'ගල්ෆ් දියවැල' හමුවන නිව්ෆවුන්ඩ්ලන්ත (Grand Banks) මුහුදු ප්‍රදේශයේ ප්‍රධාන ලක්ෂණ දෙක කුමක්ද?",
        "ඝන මීදුම හට ගැනීම සහ ලෝකයේ පොහොසත්ම මත්ස්‍ය බිම් බිහි වීම", "කොරල් පර හට ගැනීම සහ අධික උණුසුම", "මුහුදු ජලය සිඳී යාම", "ගිනිකඳු පිපිරීම්",
        "සීතල හා උණුසුම් දියවැල් මිශ්‍ර වීමෙන් ප්ලවාංග (Plankton) බහුල වී මසුන් ආකර්ෂණය වේ."),
      q(t, "ජපානයේ වෙරළ අසල හමුවන උණුසුම් 'කුරෝෂියෝ' (Kuroshio) සහ සීතල 'ඔයාෂියෝ' (Oyashio) දියවැල් නිසා ඇතිවන ආර්ථික වාසිය කුමක්ද?",
        "ලෝකයේ ප්‍රධානතම වාණිජ මත්ස්‍ය කලාපයක් නිර්මාණය වීම", "ලුණු කර්මාන්තය පමණක් දියුණු වීම", "මුහුදු ඛනිජ තෙල් සෑදීම", "හිරු එළිය වැඩි වීම",
        "උතුරු පැසිෆික් හි මෙම මිශ්‍රණ කලාපය ජපාන ධීවර කර්මාන්තයේ පදනමයි."),
      q(t, "ශ්‍රී ලංකාවේ පළමු අන්තර් මෝසම් (First Inter-monsoon) වැසි කාලසීමාව වන්නේ කුමන මාසවලදීද?",
        "මාර්තු සිට අප්‍රේල් දක්වා", "ජූනි සිට අගෝස්තු දක්වා", "දෙසැම්බර් සිට පෙබරවාරි දක්වා", "ඔක්තෝබර් සිට නොවැම්බර් දක්වා",
        "සවස් කාලයේ හා රාත්‍රියේදී ගිගුරුම් සහිත සංවහන වැසි මාර්තු–අප්‍රේල් කාලයේ ලැබේ."),
      q(t, "ශ්‍රී ලංකාවේ දෙවන අන්තර් මෝසම් කාලයේදී (ඔක්තෝබර් – නොවැම්බර්) දිවයින පුරා පුළුල් වර්ෂාපතනයක් හා ගංවතුර ඇති වන්නේ ඇයි?",
        "සංවහන වැසිවලට අමතරව බෙංගාල බොක්කේ හටගන්නා අවපාත හා සුළි කුණාටු බලපාන බැවින්", "නිරිතදිග මෝසම උපරිම වන බැවින්", "හිම දියවන බැවින්", "කච්චාන් සුළඟ හමන බැවින්",
        "මෙම කාලය ශ්‍රී ලංකාවේ සමතුලිතවම වැසි ව්‍යාප්ත වන සෘතුවයි."),
      q(t, "අධික ජල හිඟයකින් පෙළෙන ප්‍රදේශයක සාමාන්‍ය වර්ෂාපතනයට වඩා දීර්ඝ කාලයක් වර්ෂාව අඩු වීමෙන් ඇතිවන 'කාලගුණ විද්‍යාත්මක නියඟය' යනු කුමක්ද?",
        "දීර්ඝ කාලයක් පුරා සාමාන්‍යයට වඩා සැලකිය යුතු ලෙස වර්ෂාපතනය අඩු වීම", "ජලාශයක වේල්ල බිඳී යාම", "ගංගාවක් පිටාර ගැලීම", "අයිස් කඳු දියවීම",
        "කාලගුණ විද්‍යාත්මක නියඟය පසුව කෘෂිකාර්මික හා ජල විද්‍යාත්මක නියඟ බවට පත්විය හැක."),
      q(t, "වාතයේ අඩංගු සැබෑ ජල වාෂ්ප ප්‍රමාණය, එම උෂ්ණත්වයේදී වාතයට දරාගත හැකි උපරිම ජල වාෂ්ප ප්‍රමාණයට දක්වන ප්‍රතිශතය කුමක්ද?",
        "සාපේක්ෂ ආර්ද්‍රතාව (Relative Humidity)", "නිරපේක්ෂ ආර්ද්‍රතාව", "වර්ෂාපතන තීව්‍රතාව", "වාෂ්පීකරණ අනුපාතය",
        "වාතය සම්පූර්ණයෙන්ම ජල වාෂ්පවලින් සංතෘප්ත වූ විට සාපේක්ෂ ආර්ද්‍රතාව 100% ක් වේ."),
      q(t, "වායු ස්කන්ධයක උෂ්ණත්වය ඉහළ යන විට එහි ජල වාෂ්ප ප්‍රමාණය නොවෙනස්ව පවතී නම් සාපේක්ෂ ආර්ද්‍රතාවට කුමක් සිදුවේද?",
        "අඩු වේ", "වැඩි වේ", "වෙනස් නොවේ", "100% දක්වා ඉහළ යයි",
        "උණුසුම් වාතයට වැඩි ජල වාෂ්ප ප්‍රමාණයක් දරාගත හැකි බැවින් සාපේක්ෂ ආර්ද්‍රතාව පහළ බසී."),
      q(t, "හිම කැට වර්ෂාව (Hail) ඇති වීමට විශේෂයෙන්ම දායක වන වායුගෝලීය ක්‍රියාවලිය කුමක්ද?",
        "Cumulonimbus වළාකුළු තුළ ඇති ප්‍රබල ඉහළ-පහළ වායු ධාරා මගින් ජල බිඳිති නැවත නැවත අධිශීතල කලාපයට ගෙන යාම", "සමකයේ සන්සුන් වාතය", "මීදුම ඝනීභවනය වීම", "උල්කාපාත පතිත වීම",
        "අයිස් කැට වටා තට්ටු වශයෙන් අයිස් බැඳී බර වැඩි වූ පසු පොළොවට පතිත වේ."),
      q(t, "ගෝලීය උණුසුම් වීම හේතුවෙන් මුහුදු මට්ටම ඉහළ යාමට ප්‍රධාන වශයෙන් බලපාන සාධක දෙක මොනවාද?",
        "සාගර ජලයේ තාප ප්‍රසාරණය සහ ගොඩබිම ඇති ග්ලැසියර හා අයිස් තට්ටු දියවීම", "පාවෙන මුහුදු අයිස් දියවීම පමණි", "ගංගා ජලය අඩුවීම", "භූ කම්පන වැඩිවීම",
        "සාගර ජලය රත් වන විට පරිමාව ප්‍රසාරණය වීමත් ග්‍රීන්ලන්ත-ඇන්ටාක්ටික් අයිස් දියවීමත් මුහුදු මට්ටම ඉහළ දමයි."),
      q(t, "වායුගෝලයේ ඇති අධි-දූෂිත සල්ෆර් ඩයොක්සයිඩ් (SO2) සහ නයිට්‍රජන් ඔක්සයිඩ් (NOx) ජල වාෂ්ප සමඟ එක්වීමෙන් ඇතිවන පාරිසරික ගැටලුව කුමක්ද?",
        "අම්ල වැසි (Acid Rain)", "ඕසෝන් ස්තරය ගොඩනැගීම", "ගිනිකඳු පිපිරීම්", "භූගත ජලය වැඩිවීම",
        "අම්ල වැසි වනාන්තරවලට, ජලජ ජීවීන්ට හා කිරිගරුඬ/හුණුගල් ගොඩනැගිලිවලට හානි කරයි."),
      q(t, "කාලගුණ සිතියමක 'L' හෝ 'Low' අකුරින් සලකුණු කර ඇති වටකුරු සම-පීඩන රේඛා මධ්‍යස්ථානයක සාමාන්‍ය කාලගුණය කෙබඳුද?",
        "වළාකුළු සහිත, වැසි හා සුළං සහිත අස්ථාවර කාලගුණයක්", "අහස පැහැදිලි ඉතා වියළි කාලගුණයක්", "සුළං සම්පූර්ණයෙන් නැති තත්ත්වයක්", "දැඩි හිම තුහින සහිත රාත්‍රියක්",
        "අඩු පීඩන කලාපවලදී වාතය ඇතුළට ඇදී ඉහළ නැග ඝනීභවනය වී වළාකුළු හා වැසි සාදයි."),
      q(t, "සම-පීඩන රේඛා (Isobars) ඉතා ළංව (තද බෑවුමක් සේ) පිහිටි ස්ථානයක කාලගුණික ලක්ෂණය කුමක්ද?",
        "සුළඟේ වේගය ඉතා අධික වීම", "සුළඟ කිසිසේත් නොහැමීම", "උෂ්ණත්වය ශුන්‍ය වීම", "සූර්යග්‍රහණයක් ඇතිවීම",
        "කෙටි දුරකින් පීඩන වෙනස විශාල වීම (Steep Pressure Gradient) ප්‍රබල සුළං ජනනය කරයි."),
      q(t, "සමකය දෙපස 10°N සිට 10°S දක්වා වූ වායුගෝලීය තත්ත්වය හේතුවෙන් ඇමසන් වනාන්තරයේ වැසි වැඩිපුර ලැබෙන වේලාව කුමක්ද?",
        "සවස 2:00 – 4:00 අතර (Four o'clock showers)", "උදෑසන 6:00 ට", "මධ්‍යම රාත්‍රී 12:00 ට", "පෙරවරු 9:00 ට",
        "උදෑසන සිට රත්වන තෙත් වාතය දහවල් වන විට ඉහළ නැග සවස ගිගුරුම් වැසි ඇති කරයි."),
      q(t, "විශාල ගංගා නිම්නවල හෝ කඳු පාමුල නිම්නවල රාත්‍රී කාලයේ සිසිල් බර වාතය බෑවුම් දිගේ පහළට රූරා යාමෙන් ඇතිවන සුළඟ කුමක්ද?",
        "කැටබැටික් / කඳු සුළඟ (Katabatic / Mountain Breeze)", "ඇනබැටික් / නිම්න සුළඟ", "වෙළඳ සුළඟ", "මෝසම් සුළඟ",
        "දිවා කාලයේදී රත් වූ වාතය නිම්නයේ සිට කඳු මුදුන් දෙසට ඉහළ නගින විට එය ඇනබැටික් (Valley Breeze) නම් වේ."),
      q(t, "ලෝකයේ වැඩිම වාර්ෂික වර්ෂාපතනයක් ලැබෙන මව්සින්රාම් (Mawsynram) සහ චෙරාපුංජි පිහිටා ඇත්තේ කුමන රටේද?",
        "ඉන්දියාව (මේඝාලය ප්‍රාන්තයේ කාසි කඳු වැටිය)", "බ්‍රසීලය", "ඉන්දුනීසියාව", "ශ්‍රී ලංකාව",
        "බෙංගාල බොක්කේ සිට එන නිරිතදිග මෝසම් සුළං පුනීල ආකාර කඳු බෑවුම්වල ගැටීමෙන් මෙහි මි.මී. 11,000+ වැසි ලැබේ."),
      q(t, "දේශගුණික දත්ත සටහන් කරන 'දේශගුණ ප්‍රස්තාරයක' (Climograph / Climate Graph) තීරු මගින් සහ රේඛාව මගින් පිළිවෙළින් පෙන්වන්නේ මොනවාද?",
        "මාසික වර්ෂාපතනය (තීරු) සහ මාසික සාමාන්‍ය උෂ්ණත්වය (රේඛාව)", "සුළං වේගය සහ පීඩනය", "ජනගහනය සහ භූමි ප්‍රමාණය", "වගා බිම් සහ වනාන්තර",
        "Climograph එකක් දෙස බැලීමෙන් ප්‍රදේශය උතුරු හෝ දකුණු අර්ධගෝලයේද යන්න සහ දේශගුණ කලාපය හඳුනාගත හැක."),
      q(t, "දකුණු අර්ධගෝලයේ (උදා: පර්ත් හෝ කේප්ටවුන්) දේශගුණ ප්‍රස්තාරයක උෂ්ණත්ව රේඛාවේ හැඩය කෙසේ දිස්වේද?",
        "ජූනි–ජූලි මාසවල පහළට නැමුණු 'U' හැඩයක් (ජනවාරි–පෙබරවාරි උණුසුම්ම කාලය)", "ජූලි මාසයේ උච්චතම ස්ථානයක්", "සම්පූර්ණ සරල රේඛාවක්", "මාර්තු වල පමණක් වැටීමක්",
        "දකුණු අර්ධගෝලයේ ජූනි-අගෝස්තු ශීත සෘතුව වන අතර දෙසැම්බර්-පෙබරවාරි ග්‍රීෂ්ම සෘතුවයි."),
      q(t, "ස්ටෙප් (Steppe / BS) හෙවත් අර්ධ ශුෂ්ක දේශගුණ කලාපයේ ස්වභාවික වෘක්ෂලතා සැකැස්ම කුමක්ද?",
        "කෙටි තෘණ බිම් හා විසිරුණු කටු පඳුරු", "උස සදාහරිත රූස්ස ගස්", "කේතුධර වනාන්තර", "කඩොලාන වනාන්තර",
        "කාන්තාර හා තෙත් බිම් අතර සංක්‍රමණික කලාපයක් ලෙස ස්ටෙප් කලාප පවතී."),
      q(t, "මෝසම් කාලගුණික ලක්ෂණ සහිත දකුණු හා අග්නිදිග ආසියානු කලාපයේ ප්‍රධාන කෘෂිකාර්මික බෝගය කුමක්ද?",
        "වී ගොවිතැන (Paddy Cultivation)", "ඔලිව් වගාව", "කෝන් සහ රයි", "ටියුලිප් මල්",
        "ග්‍රීෂ්ම මෝසම් වැසි සහ උණුසුම් උෂ්ණත්වය වී වගාවට ඉතා යෝග්‍ය වේ."),
      q(t, "අධික සුළං සහිත ස්ථානයක ගස් එකම දිශාවකට ඇල වී වැඩීම භූගෝල විද්‍යාවේදී පෙන්වා දෙන්නේ කුමක්ද?",
        "එම ප්‍රදේශයේ පවතින ප්‍රමුඛ සුළං දිශාව (Prevailing Wind Direction)", "භූගත ජල මට්ටම", "පසේ ආම්ලිකතාව", "චුම්භක ක්ෂේත්‍රය",
        "වෙරළබඩ ප්‍රදේශවල පොල් හා කස ගස් ප්‍රමුඛ මුහුදු සුළං දිශාවට ඇල වී තිබෙනු දැකිය හැක."),
      q(t, "දේශගුණික විපර්යාස අවම කිරීමේ 'අවම කිරීමේ උපායමාර්ගයක්' (Mitigation) වන්නේ පහත කුමක්ද?",
        "ෆොසිල ඉන්ධන වෙනුවට සූර්ය හා සුළං වැනි පුනර්ජනනීය බලශක්ති භාවිතය හා නැවත වන වගාව", "වෙරළ ආරක්ෂක බැමි බැඳීම පමණි", "උස් ගොඩනැගිලි තැනීම", "නියඟයට ඔරොත්තු දෙන බීජ සිටුවීම",
        "විමෝචන අඩු කිරීම Mitigation වන අතර බලපෑම්වලට හැඩගැසීම Adaptation නම් වේ."),
      q(t, "දේශගුණික විපර්යාස සඳහා 'අනුවර්තනය වීමේ' (Adaptation) පියවරකට උදාහරණයක් කුමක්ද?",
        "ලවණතාවට හා නියඟයට ඔරොත්තු දෙන වී ප්‍රභේද හඳුන්වා දීම සහ ගංවතුර පූර්ව අනතුරු ඇඟවීම් ශක්තිමත් කිරීම", "ගල් අඟුරු බලාගාර වැඩි කිරීම", "වනාන්තර එළි කිරීම", "ප්ලාස්ටික් දහනය කිරීම",
        "දැනටමත් සිදුවන කාලගුණික වෙනස්කම්වල හානිය අවම කර ගනිමින් ජීවත් වීමට හැඩගැසීම Adaptation වේ."),
      q(t, "වායුගෝලයේ ජල වාෂ්ප හා වළාකුළු පෘථිවියේ තාප තුලනයට (Heat Budget) උපකාරී වන්නේ කෙසේද?",
        "දිවා කාලයේදී සූර්ය කිරණ කොටසක් පරාවර්තනය කරමින් සහ රාත්‍රියේදී භෞමික තාපය රඳවා ගනිමින්", "සියලු තාපය අභ්‍යවකාශයට යවමින්", "පෘථිවි හරය උණුසුම් කරමින්", "වායුගෝලය ඉවත් කරමින්",
        "මේ නිසා වළාකුළු නොමැති කාන්තාරවල දහවල් අධික උණුසුමත් රාත්‍රී අධික සීතලත් පවතී."),
      q(t, "කාන්තාර ප්‍රදේශවල රාත්‍රී කාලය ඉතා සිසිල් වීමට ප්‍රධානතම හේතුව කුමක්ද?",
        "වළාකුළු හා ජල වාෂ්ප අඩු බැවින් රැස් කළ තාපය ඉක්මනින් අභ්‍යවකාශයට විකිරණය වී යාම", "හිම වැටීම නිසා", "ගස් වැඩි නිසා", "සාගර ළඟ නිසා",
        "පැහැදිලි අහස සහ වියළි වාතය නිසා කාන්තාරවල දෛනික උෂ්ණත්ව පරාසය 30°C ඉක්මවිය හැක."),
      q(t, "භූගෝල විද්‍යාවේදී 'පෙරමුණු' (Weather Front) ලෙස හඳුන්වන්නේ කුමක්ද?",
        "වෙනස් උෂ්ණත්ව හා ආර්ද්‍රතා ලක්ෂණ ඇති වායු ස්කන්ධ දෙකක් එකිනෙක හමුවන සංක්‍රමණ කලාපය", "සමකයේ නියත සුළං තීරුව", "ගිනිකඳු ආවාටයක සීමාව", "මුහුදු වෙරළේ වැලි තීරුව",
        "සීතල පෙරමුණු (Cold Front) සහ උණුසුම් පෙරමුණු (Warm Front) මධ්‍ය අක්ෂාංශ කාලගුණය පාලනය කරයි."),
      q(t, "කාලගුණ විද්‍යාවේදී 'වාෂ්පීභවනය' (Evapotranspiration) යනු කුමක්ද?",
        "භූමියෙන් හා ජලාශවලින් සිදුවන වාෂ්පීකරණයත් ශාක පත්‍ර මගින් සිදුවන උත්ස්වේදනයත් යන දෙකෙහිම එකතුවයි", "වර්ෂාව පොළොවට වැටීම පමණි", "අයිස් ඝන වීමයි", "සුළං වේගය මැනීමයි",
        "ලයිසිමීටර (Lysimeter) මගින් වාෂ්පීභවනය හා ජල සමතුලිතතාව මනිනු ලැබේ."),
      q(t, "මෝසම් දේශගුණය සහ සමක දේශගුණය අතර පවතින ප්‍රධානතම සමානකම කුමක්ද?",
        "වසර පුරා ඉහළ මාසික උෂ්ණත්වයක් (සෑම මාසයකම 18°C ට වැඩි) පැවතීම", "වසර පුරා හිම පතනය", "දිගු ශීත සෘතුව", "සුළං සම්පූර්ණයෙන් නැතිවීම",
        "දෙකම Köppen 'A' (නිවර්තන) දේශගුණ කාණ්ඩයට අයත් වන නමුත් වර්ෂාපතන රටාවෙන් වෙනස් වේ."),
      q(t, "වයඹදිග යුරෝපයේ (උදා: බ්‍රිතාන්‍යය, නෙදර්ලන්තය) පවතින දේශගුණ කලාපය හඳුන්වන්නේ කුමන නමකින්ද?",
        "සෞම්‍ය සමුද්‍රික දේශගුණය (Temperate Maritime / Marine West Coast - Cfb)", "මධ්‍යධරණී දේශගුණය", "ටයිගා දේශගුණය", "නිවර්තන මෝසම් දේශගුණය",
